declarations.elaborated_type:
∀ {N : ℕ} {holonomy : D0.Role → ℂ} {unitary : ∀ (r : D0.Role), star (holonomy r) * holonomy r = 1}
  {support : Set D0.Role} {support_spec : ∀ r ∉ support, holonomy r = 1} {holonomy_1 : D0.Role → ℂ}
  {unitary_1 : ∀ (r : D0.Role), star (holonomy_1 r) * holonomy_1 r = 1} {support_1 : Set D0.Role}
  {support_spec_1 : ∀ r ∉ support_1, holonomy_1 r = 1},
  { holonomy := holonomy, unitary := unitary, support := support, support_spec := support_spec } =
      { holonomy := holonomy_1, unitary := unitary_1, support := support_1, support_spec := support_spec_1 } →
    holonomy = holonomy_1 ∧ support = support_1
